INSERT INTO feature VALUES('grades','effects','Grades on a hold','temporary-access','partial','uncommon','mainstream languages','A hold written var[1] s = e holds its value at grade one: the entry is a value made in place, the held value is never copied while held (a copying read refused by name), and exclusive accesses lend it; a string held at grade one is written in place, a copy refused by name. The bracket is a numeral; the default grade is unwritten. The emitter does not yet read the grade to drop the holder count on a write-back.','core-term core-checker surface-grammar surface-lowering','corpus/model/control/held-unique.gandr corpus/pathological/control/held-unique.gandr corpus/model/strings/unique-write.gandr corpus/pathological/strings/unique-write.gandr','corpus/ledger/features/grades.gandr','#1219 #1175');
